import{_ as i,o as n,c as t,ah as r}from"./chunks/framework.Bja9t6Wf.js";const g=JSON.parse('{"title":"Das Konzept: Pointillismus des Kapitals","description":"","frontmatter":{},"headers":[],"relativePath":"pointillismus.md","filePath":"pointillismus.md"}'),s={name:"pointillismus.md"};function a(l,e,o,d,u,h){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="das-konzept-pointillismus-des-kapitals" tabindex="-1">Das Konzept: Pointillismus des Kapitals <a class="header-anchor" href="#das-konzept-pointillismus-des-kapitals" aria-label="Permalink to &quot;Das Konzept: Pointillismus des Kapitals&quot;">​</a></h1><p>Der &quot;Pointillismus des Kapitals&quot; ist eine zentrale satirische Metapher, die sich durch die gesamte Mockumentary &quot;Das Horten-Mysterium&quot; zieht. Sie beschreibt die Methode, große, potenziell problematische Handlungen in eine Vielzahl kleiner, scheinbar harmloser Einzelteile zu zerlegen, um sie unsichtbar oder unbedeutend erscheinen zu lassen.</p><p>Genau wie der französische Maler Georges Seurat in der Kunst des <strong>Pointillismus</strong> seine Bilder aus tausenden winzigen Farbpunkten zusammensetzte, die erst aus der Distanz ein zusammenhängendes Motiv ergeben, werden hier große finanzielle oder politische Manöver in unzählige kleine Transaktionen oder Aktionen aufgespalten.</p><h2 id="anwendungsfalle-in-der-mockumentary" tabindex="-1">Anwendungsfälle in der Mockumentary <a class="header-anchor" href="#anwendungsfalle-in-der-mockumentary" aria-label="Permalink to &quot;Anwendungsfälle in der Mockumentary&quot;">​</a></h2><h3 id="_1-die-spenden-stuckelung-politik" tabindex="-1">1. Die Spenden-Stückelung (Politik) <a class="header-anchor" href="#_1-die-spenden-stuckelung-politik" aria-label="Permalink to &quot;1. Die Spenden-Stückelung (Politik)&quot;">​</a></h3><ul><li><strong>Die Methode:</strong> Eine Millionenspende an eine politische Partei wird nicht als ein großer, meldepflichtiger Betrag überwiesen, sondern als eine Vielzahl kleinerer Spenden (z.B. 49.000 € pro Stück), die jeweils knapp unter der gesetzlichen Meldegrenze liegen.</li><li><strong>Die satirische Rechtfertigung:</strong> Ein Politiker (wie unser fiktiver Minister Gönner) verteidigt dies nicht als Trick, sondern als „ästhetische Entscheidung“ – eine Hommage an die Kunst, die die „Schönheit der Kleinigkeit“ feiert.</li></ul><h3 id="_2-die-schredder-affare-datenvernichtung" tabindex="-1">2. Die Schredder-Affäre (Datenvernichtung) <a class="header-anchor" href="#_2-die-schredder-affare-datenvernichtung" aria-label="Permalink to &quot;2. Die Schredder-Affäre (Datenvernichtung)&quot;">​</a></h3><ul><li><strong>Die Methode:</strong> Anstatt eine Festplatte einfach zu löschen, wird sie in tausende winzige physische Partikel geschreddert. Die Information ist nicht mehr als Ganzes vorhanden, nur noch als unlesbares „Rauschen“.</li><li><strong>Die satirische Parallele:</strong> Die Zerstörung von Daten folgt demselben Prinzip wie die Stückelung von Spenden: Was in seine Einzelteile zerlegt ist, verliert seine Beweiskraft und seine Geschichte.</li></ul><h3 id="_3-die-arisierung-rustung-historie" tabindex="-1">3. Die Arisierung &amp; Rüstung (Historie) <a class="header-anchor" href="#_3-die-arisierung-rustung-historie" aria-label="Permalink to &quot;3. Die Arisierung &amp; Rüstung (Historie)&quot;">​</a></h3><ul><li><strong>Die Methode:</strong> Helmut Horten übernimmt nicht nur Warenhäuser (&quot;Arisierung&quot;), sondern investiert gleichzeitig in die Rüstungsindustrie (Flugzeugwerk Johannisthal). Jede einzelne Beteiligung wird als isolierter Geschäftsschritt präsentiert.</li><li><strong>Die satirische Darstellung:</strong> In der Mockumentary argumentiert Horten, er habe durch die Rüstungsproduktion nur „die Mobilität der Zukunft mitgestaltet“ – während die systematische Ausbeutung von Zwangsarbeitern als notwendiges „Detail im Getriebe“ untergeht.</li></ul><h2 id="fazit" tabindex="-1">Fazit <a class="header-anchor" href="#fazit" aria-label="Permalink to &quot;Fazit&quot;">​</a></h2><p>Der &quot;Pointillismus des Kapitals&quot; ist die Kunst, durch <strong>Zerteilung</strong> und <strong>Wiederholung</strong> die Spuren großer Taten zu verwischen. Er ist die Ästhetik der Verschleierung – ein Leitmotiv, das die historische Gier mit der modernen politischen Vertuschung auf zynische, aber elegante Weise verbindet.</p>',12)])])}const p=i(s,[["render",a]]);export{g as __pageData,p as default};
